function median(l) {
    l.sort((a, b) => a - b);
    const mid = Math.floor(l.length / 2);
    return l.length % 2 === 0 ? (l[mid - 1] + l[mid]) / 2 : l[mid];
}

function count_divisors(n) {
  let count = 0;
  for (let i = 1; i <= n; i++) {
    if (n % i === 0) {
      count++;
    }
  }
  return count % 2 === 0;
}

function move_num(test_str){
  let num_array = [];
  let non_num_array = [];

  for(let i=0; i<test_str.length; i++){
    if(Number.isInteger(parseInt(test_str[i]))){
      num_array.push(test_str[i]);
    } else {
      non_num_array.push(test_str[i]);
    }
  }

  return non_num_array.join('') + num_array.join('');
}

function last(arr, x) {
  let left = 0;
  let right = arr.length - 1;

  while (left <= right) {
    const mid = Math.floor((left + right) / 2);

    if (arr[mid] === x) {
      // If the element is found, move the left pointer to the right
      left = mid + 1;
    } else if (arr[mid] < x) {
      // If the element is greater than x, move the left pointer to the right
      left = mid + 1;
    } else {
      // If the element is less than x, move the right pointer to the left
      right = mid - 1;
    }
  }

  // Return the last position of the element
  return left - 1;
}

