function parse_music(music_string) {
    const notes = music_string.split(' ');
    const beats = [];

    for (let note of notes) {
        if (note === 'o') {
            beats.push(4);
        } else if (note === 'o|') {
            beats.push(2);
        } else if (note === '.|') {
            beats.push(1);
        }
    }

    return beats;
}

