function fibfib(n) {
    if (n === 0 || n === 1) return 0;
    if (n === 2) return 1;

    let a = 0, b = 0, c = 1, d = 0;
    for (let i = 3; i <= n; i++) {
        d = a + b + c;
        a = b;
        b = c;
        c = d;
    }
    return d;
}

function is_multiply_prime(a) {
    if (a < 2 || a >= 100) return false;

    let primeFactors = [];
    for (let i = 2; i <= a; i++) {
        while (a % i === 0) {
            primeFactors.push(i);
            a /= i;
        }
    }

    return primeFactors.length === 3 && primeFactors.every(factor => isPrime(factor));
}

